css:
body {
  font-family: "Helvetica", "Arial", sans-serif;
  font-size: 14px;
  margin: 30px;
  color: #222;
}

.report-container {
  max-width: 900px;
  margin: auto;
}

h1 {
  margin-bottom: 10px;
  color: #004b8d;
}

h2 {
  margin-top: 20px;
  text-align: center; 
}

.section {
  margin: 20px 0;
}

.row {
  display: flex;
  flex-wrap: wrap;
  margin-bottom: 10px;
}

.col {
  padding: 5px 10px;
  box-sizing: border-box;
}

.col-30 { width: 30%; }
.col-33 { width: 33.3333%; }
.col-70 { width: 70%; }
.col-100 { width: 100%; }

.company-logo img {
  max-width: 100px;
  height: auto;
}

.med-table {
  width: 100%;
  border-collapse: collapse;
  margin: 10px;
}

.med-table th, .med-table td {
  border: 1px solid #ccc;
  padding: 6px;
  text-align: left;
}

.med-table th {
  background-color: #f0f0f0;
}

@media print {
  body {
    margin: 10mm;
  }

  .company-logo img {
    max-width: 80px;
  }
}
